describe('Inventory Page - Product List Display', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('[data-test="login-container"]').within(() => {
      cy.get('[data-test="username"]').type('standard_user');
      cy.get('[data-test="password"]').type('secret_sauce');
      cy.get('[data-test="login-button"]').click();
    });
  });

  it('should display complete product cards with non-empty names and prices', () => {
    cy.get('[data-test="inventory-container"]').should('be.visible');
    cy.get('[data-test="inventory-list"]').should('contain', '6');
    cy.get('[data-test="inventory-item"]').each(($item, index) => {
      cy.get(`[data-test="inventory-item-name"]`).should('be.visible');
      cy.get(`[data-test="inventory-item-name"]`).should('contain', 'Product');
      cy.get(`[data-test="inventory-item-price"]`).should('be.visible');
      cy.get(`[data-test="inventory-item-price"]`).should('contain', '$');
      cy.get(`[data-test="inventory-item-name"]`).should('have.length.greaterThan', 0);
      cy.get(`[data-test="inventory-item-price"]`).should('have.length.greaterThan', 0);
    });
  });

  it('should handle edge case when product list is empty', () => {
    cy.visit('/inventory');
    cy.get('[data-test="inventory-container"]').should('be.visible');
    cy.get('[data-test="inventory-list"]').should('contain', '0');
    cy.get('[data-test="inventory-item"]').should('not.exist');
    cy.get('[data-test="inventory-item-name"]').should('not.exist');
    cy.get('[data-test="inventory-item-price"]').should('not.exist');
  });
});
